/* * @lc app=leetcode id=1044 lang=kotlin * * [1044] Longest Duplicate Substring */ class Solution { fun longestDupSubstring(s: String): String = generateSequence(Triple(1, s.length - 1, "")) { (l, r, ans) -> if (l > r) null else ((l + r) / 2).let { m -> 1_000_000_000_039L.let { mod -> 313L.let { base -> (1 until m).fold(1L) { acc, _ -> (acc * base) % mod }.let { pow -> HashMap<Long, MutableList<Int>>().let { map -> (0..s.length - m).fold(Pair<Long, String?>(0L, null)) { (h, found), i -> if (found != null) Pair<Long, String?>(h, found) else (if (i == 0) (0 until m).fold(0L) { acc, j -> (acc * base + (s[j] - 'a')) % mod } else (((h - (s[i - 1] - 'a') * pow % mod) % mod + mod) % mod * base + (s[i + m - 1] - 'a')) % mod).let { curH -> map.getOrPut(curH) { mutableListOf() }.let { list -> if (list.any { s.regionMatches(it, s, i, m) }) Pair<Long, String?>(curH, s.substring(i, i + m)) else list.add(i).let { Pair<Long, String?>(curH, null) } } } }.second?.let { Triple(m + 1, r, it) } ?: Triple(l, m - 1, ans) } } } } } }.last().third }